// Assemble the static site (only what the browser loads) into dist/.
// Used by the Cloudflare deploy and the GitHub Pages workflow, so neither can ever pick up
// server.mjs, .env, the audio tools or docs.
import { rm, mkdir, cp } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), '..');
const OUT = path.join(ROOT, 'dist');
// assets/voice holds announcer lines already generated by the dev server; shipping them means the
// deployed Worker serves them as static files instead of calling the TTS model again.
const INCLUDE = ['index.html', 'style.css', 'src', 'assets/audio', 'assets/voice'];

await rm(OUT, { recursive: true, force: true });
await mkdir(OUT);
for (const rel of INCLUDE) {
  const from = path.join(ROOT, rel);
  if (existsSync(from)) await cp(from, path.join(OUT, rel), { recursive: true });
}
console.log(`dist/ ← ${INCLUDE.filter((r) => existsSync(path.join(ROOT, r))).join(', ')}`);
